mm_answer_authpassword(int sock, Buffer *m)
{
	static int call_count;
	char *passwd;
	int authenticated;
	u_int plen;

	if (!options.password_authentication)
		fatal("%s: password authentication not enabled", __func__);
	passwd = buffer_get_string(m, &plen);
	/* Only authenticate if the context is valid */
	authenticated = options.password_authentication &&
	    auth_password(authctxt, passwd);
	explicit_bzero(passwd, strlen(passwd));
	free(passwd);

	buffer_clear(m);
	buffer_put_int(m, authenticated);

	debug3("%s: sending result %d", __func__, authenticated);
	mm_request_send(sock, MONITOR_ANS_AUTHPASSWORD, m);

	call_count++;
	if (plen == 0 && call_count == 1)
		auth_method = "none";
	else
		auth_method = "password";

	/* Causes monitor loop to terminate if authenticated */
	return (authenticated);
}

static vpx_codec_err_t decoder_decode(vpx_codec_alg_priv_t *ctx,
 const uint8_t *data, unsigned int data_sz,
 void *user_priv, long deadline) {
 const uint8_t *data_start = data;
 const uint8_t * const data_end = data + data_sz;
 vpx_codec_err_t res;
 uint32_t frame_sizes[8];
 int frame_count;

 if (data == NULL && data_sz == 0) {
    ctx->flushed = 1;
 return VPX_CODEC_OK;
 }

  ctx->flushed = 0;

 if (ctx->frame_workers == NULL) {
 const vpx_codec_err_t res = init_decoder(ctx);
 if (res != VPX_CODEC_OK)
 return res;
 }

  res = vp9_parse_superframe_index(data, data_sz, frame_sizes, &frame_count,
                                   ctx->decrypt_cb, ctx->decrypt_state);
 if (res != VPX_CODEC_OK)
 return res;

 if (ctx->frame_parallel_decode) {
 if (frame_count > 0) {
 int i;

 for (i = 0; i < frame_count; ++i) {
 const uint8_t *data_start_copy = data_start;
 const uint32_t frame_size = frame_sizes[i];
 if (data_start < data
 || frame_size > (uint32_t) (data_end - data_start)) {
          set_error_detail(ctx, "Invalid frame size in index");
 return VPX_CODEC_CORRUPT_FRAME;
 }

 if (ctx->available_threads == 0) {
 if (ctx->num_cache_frames < FRAME_CACHE_SIZE) {
            wait_worker_and_cache_frame(ctx);
 } else {
            set_error_detail(ctx, "Frame output cache is full.");
 return VPX_CODEC_ERROR;
 }
 }

        res = decode_one(ctx, &data_start_copy, frame_size, user_priv,
                         deadline);
 if (res != VPX_CODEC_OK)
 return res;
        data_start += frame_size;
 }
 } else {
 if (ctx->available_threads == 0) {
 if (ctx->num_cache_frames < FRAME_CACHE_SIZE) {
          wait_worker_and_cache_frame(ctx);
 } else {
          set_error_detail(ctx, "Frame output cache is full.");
 return VPX_CODEC_ERROR;
 }
 }

      res = decode_one(ctx, &data, data_sz, user_priv, deadline);
 if (res != VPX_CODEC_OK)
 return res;
 }
 } else {
 if (frame_count > 0) {
 int i;

 for (i = 0; i < frame_count; ++i) {
 const uint8_t *data_start_copy = data_start;
 const uint32_t frame_size = frame_sizes[i];
 vpx_codec_err_t res;
 if (data_start < data
 || frame_size > (uint32_t) (data_end - data_start)) {
          set_error_detail(ctx, "Invalid frame size in index");
 return VPX_CODEC_CORRUPT_FRAME;
 }

        res = decode_one(ctx, &data_start_copy, frame_size, user_priv,
                         deadline);
 if (res != VPX_CODEC_OK)
 return res;

        data_start += frame_size;
 }
 } else {
 while (data_start < data_end) {
 const uint32_t frame_size = (uint32_t) (data_end - data_start);
 const vpx_codec_err_t res = decode_one(ctx, &data_start, frame_size,
                                               user_priv, deadline);
 if (res != VPX_CODEC_OK)
 return res;

 while (data_start < data_end) {
 const uint8_t marker = read_marker(ctx->decrypt_cb,
                                             ctx->decrypt_state, data_start);
 if (marker)
 break;
 ++data_start;
 }
 }
 }
 }

 return res;
}

METHODDEF(JDIMENSION)
get_32bit_row(j_compress_ptr cinfo, cjpeg_source_ptr sinfo)
/* This version is for reading 32-bit pixels */
{
  bmp_source_ptr source = (bmp_source_ptr)sinfo;
  JSAMPARRAY image_ptr;
  register JSAMPROW inptr, outptr;
  register JDIMENSION col;

  if (source->use_inversion_array) {
    /* Fetch next row from virtual array */
    source->source_row--;
    image_ptr = (*cinfo->mem->access_virt_sarray)
      ((j_common_ptr)cinfo, source->whole_image,
       source->source_row, (JDIMENSION)1, FALSE);
    inptr = image_ptr[0];
  } else {
    if (!ReadOK(source->pub.input_file, source->iobuffer, source->row_width))
      ERREXIT(cinfo, JERR_INPUT_EOF);
    inptr = source->iobuffer;
  }

  /* Transfer data.  Note source values are in BGR order
   * (even though Microsoft's own documents say the opposite).
   */
  outptr = source->pub.buffer[0];
  if (cinfo->in_color_space == JCS_EXT_BGRX ||
      cinfo->in_color_space == JCS_EXT_BGRA) {
    MEMCOPY(outptr, inptr, source->row_width);
  } else if (cinfo->in_color_space == JCS_CMYK) {
    for (col = cinfo->image_width; col > 0; col--) {
      /* can omit GETJSAMPLE() safely */
      JSAMPLE b = *inptr++, g = *inptr++, r = *inptr++;
      rgb_to_cmyk(r, g, b, outptr, outptr + 1, outptr + 2, outptr + 3);
      inptr++;                          /* skip the 4th byte (Alpha channel) */
      outptr += 4;
    }
  } else {
    register int rindex = rgb_red[cinfo->in_color_space];
    register int gindex = rgb_green[cinfo->in_color_space];
    register int bindex = rgb_blue[cinfo->in_color_space];
    register int aindex = alpha_index[cinfo->in_color_space];
    register int ps = rgb_pixelsize[cinfo->in_color_space];

    if (aindex >= 0) {
      for (col = cinfo->image_width; col > 0; col--) {
        outptr[bindex] = *inptr++;      /* can omit GETJSAMPLE() safely */
        outptr[gindex] = *inptr++;
        outptr[rindex] = *inptr++;
        outptr[aindex] = *inptr++;
        outptr += ps;
      }
    } else {
      for (col = cinfo->image_width; col > 0; col--) {
        outptr[bindex] = *inptr++;      /* can omit GETJSAMPLE() safely */
        outptr[gindex] = *inptr++;
        outptr[rindex] = *inptr++;
        inptr++;                        /* skip the 4th byte (Alpha channel) */
        outptr += ps;
      }
    }
  }

  return 1;
}

